with content as (
 select * from jsonb_to_recordset($content$[
  {"level":"A1","title":"Paul's Reading Corner","body":"Paul has an idea. He wants a reading corner at his school. He talks about it with his friends. They like the idea, but there is no reading corner yet.\n\nOne day, Paul draws a small plan. He chooses a quiet place in the classroom. He writes a list: books, a box and a small sign.\n\nPaul asks his teacher for permission. She says yes. She gives him an old box. Paul writes \"Our Books\" on a piece of paper and puts it on the box.\n\nHis friends bring five books. Paul puts them in the box. During the break, two children sit near the box and read.\n\nThe reading corner is small, but it is real now. Paul is happy. He learns that an idea needs an action. A list, a question and a first book can start something useful.","summary_fr":"Paul veut créer un coin lecture à l'école. Il dessine un plan, demande la permission, prépare une boîte et reçoit cinq livres pour rendre son idée réelle.","translation_fr":"Paul a une idée. Il veut un coin lecture dans son école. Il en parle avec ses amis. Ils aiment l'idée, mais il n'y a pas encore de coin lecture.\n\nUn jour, Paul dessine un petit plan. Il choisit un endroit calme dans la classe. Il écrit une liste : des livres, une boîte et une petite affiche.\n\nPaul demande la permission à son professeur. Elle accepte. Elle lui donne une vieille boîte. Paul écrit « Nos livres » sur une feuille et la met sur la boîte.\n\nSes amis apportent cinq livres. Paul les met dans la boîte. Pendant la pause, deux enfants s'assoient près de la boîte et lisent.\n\nLe coin lecture est petit, mais il est réel maintenant. Paul est content. Il apprend qu'une idée a besoin d'une action. Une liste, une question et un premier livre peuvent commencer quelque chose d'utile.","knowledge_point":"L'apprenant découvre qu'une idée devient réelle grâce à des actions simples : planifier, demander la permission et rassembler les premières ressources.","vocabulary":[{"word":"corner","part_of_speech":"noun","translation_fr":"coin","definition":"A small area for a particular purpose.","example":"He wants a reading corner."},{"word":"yet","part_of_speech":"adverb","translation_fr":"encore","definition":"Used when something has not happened.","example":"There is no reading corner yet."},{"word":"quiet","part_of_speech":"adjective","translation_fr":"calme","definition":"With little noise.","example":"He chooses a quiet place."},{"word":"sign","part_of_speech":"noun","translation_fr":"affiche, panneau","definition":"Words or pictures giving information.","example":"The box needs a small sign."},{"word":"permission","part_of_speech":"noun","translation_fr":"permission","definition":"Agreement to do something.","example":"Paul asks his teacher for permission."},{"word":"bring","part_of_speech":"verb","translation_fr":"apporter","definition":"To carry something to a place.","example":"His friends bring books."},{"word":"break","part_of_speech":"noun","translation_fr":"pause","definition":"A short rest between school activities.","example":"Children read during the break."},{"word":"useful","part_of_speech":"adjective","translation_fr":"utile","definition":"Helpful for a purpose.","example":"They start something useful."}],"questions":[{"type":"mcq","question":"What is Paul's idea?","options":["A reading corner","A football team","A music show","A new classroom"],"answer":"A reading corner","explanation_fr":"Paul veut créer un coin lecture."},{"type":"mcq","question":"Where does he choose a place?","options":["In the classroom","In the street","At his home","In a shop"],"answer":"In the classroom","explanation_fr":"Il choisit un endroit calme dans la classe."},{"type":"mcq","question":"What is on his list?","options":["Books, a box and a sign","Chairs, food and a ball","Paper, pens and a phone","A desk, a lamp and a computer"],"answer":"Books, a box and a sign","explanation_fr":"Sa liste contient ces trois éléments."},{"type":"mcq","question":"Who gives permission?","options":["His teacher","His friend","His sister","A reader"],"answer":"His teacher","explanation_fr":"Le professeur accepte le projet."},{"type":"mcq","question":"What does the teacher give Paul?","options":["An old box","Five books","A new desk","A reading lamp"],"answer":"An old box","explanation_fr":"Elle lui donne une vieille boîte."},{"type":"mcq","question":"How many books do his friends bring?","options":["Five","Two","Ten","One"],"answer":"Five","explanation_fr":"Ses amis apportent cinq livres."},{"type":"mcq","question":"What do two children do during the break?","options":["Sit near the box and read","Play football outside","Draw on the box","Take the books home"],"answer":"Sit near the box and read","explanation_fr":"Ils utilisent le coin lecture pendant la pause."},{"type":"true_false","question":"The reading corner exists before Paul makes a plan.","options":["True","False"],"answer":"False","explanation_fr":"Au début, l'idée n'est pas encore réalisée."},{"type":"true_false","question":"Paul's first actions help make the idea real.","options":["True","False"],"answer":"True","explanation_fr":"Le plan, la demande et les livres concrétisent l'idée."},{"type":"open","question":"What small action can turn one of your ideas into something real?","options":[],"answer":"I can write a short list, ask for permission and find the first resource I need.","explanation_fr":"La réponse doit proposer une première action simple et concrète."}],"grammar":[{"point":"Want plus noun","explanation_fr":"Want peut être suivi directement d'un nom pour exprimer ce qu'on souhaite.","example":"He wants a reading corner."},{"point":"There is for existence","explanation_fr":"There is indique l'existence d'une chose singulière.","example":"There is no reading corner yet."}],"discussion":["What useful idea do you have?","Who should you ask before starting?","What is the first resource you need?"]},
  {"level":"A2","title":"The Community Book Box","body":"A group of neighbours often talks about reading. Many children finish school books but have few stories to read at home. During a meeting, Esther suggests a community book box where families can share books.\n\nEveryone likes the suggestion, but the meeting moves to another subject. Esther notices that good ideas can disappear when nobody chooses the next action. After the meeting, she asks two neighbours to help her.\n\nThey visit the community centre and speak to the manager. He allows them to place a strong box near the entrance. One neighbour paints the box, another prepares a simple notebook, and Esther writes a message asking for books in good condition.\n\nFor the first week, they collect twelve books. They write each title in the notebook and agree that children should return a book before taking another one. On Saturday, several children visit the box and choose stories.\n\nNot everything is perfect. Two books arrive with damaged pages, and the group decides not to include them. They also need a dry place for the box when it rains.\n\nThe project is still small, but it has moved beyond conversation. Esther understands that action does not require knowing every future detail. It requires a responsible first step, people who share the work and a willingness to solve problems as they appear.","summary_fr":"Esther transforme l'idée d'une boîte à livres communautaire en projet réel avec deux voisins. Ils obtiennent un emplacement, collectent douze livres et résolvent les premiers problèmes ensemble.","translation_fr":"Un groupe de voisins parle souvent de lecture. Beaucoup d'enfants terminent les livres scolaires mais ont peu d'histoires à lire à la maison. Pendant une réunion, Esther suggère une boîte à livres communautaire où les familles peuvent partager des livres.\n\nTout le monde aime la suggestion, mais la réunion passe à un autre sujet. Esther remarque que les bonnes idées peuvent disparaître quand personne ne choisit la prochaine action. Après la réunion, elle demande à deux voisins de l'aider.\n\nIls visitent le centre communautaire et parlent au responsable. Il les autorise à placer une boîte solide près de l'entrée. Un voisin peint la boîte, un autre prépare un carnet simple et Esther écrit un message demandant des livres en bon état.\n\nPendant la première semaine, ils collectent douze livres. Ils écrivent chaque titre dans le carnet et conviennent que les enfants doivent rendre un livre avant d'en prendre un autre. Samedi, plusieurs enfants visitent la boîte et choisissent des histoires.\n\nTout n'est pas parfait. Deux livres arrivent avec des pages abîmées et le groupe décide de ne pas les inclure. Ils ont aussi besoin d'un endroit sec pour la boîte quand il pleut.\n\nLe projet est encore petit, mais il est allé au-delà de la conversation. Esther comprend que l'action n'exige pas de connaître tous les détails futurs. Elle exige un premier pas responsable, des personnes qui partagent le travail et la volonté de résoudre les problèmes quand ils apparaissent.","knowledge_point":"L'apprenant découvre comment une première action responsable, la répartition du travail et l'adaptation transforment une idée collective en projet.","vocabulary":[{"word":"suggest","part_of_speech":"verb","translation_fr":"suggérer","definition":"To offer an idea for consideration.","example":"Esther suggests a book box."},{"word":"notice","part_of_speech":"verb","translation_fr":"remarquer","definition":"To become aware of something.","example":"She notices that ideas can disappear."},{"word":"manager","part_of_speech":"noun","translation_fr":"responsable","definition":"The person in charge of a place or activity.","example":"They speak to the centre manager."},{"word":"entrance","part_of_speech":"noun","translation_fr":"entrée","definition":"The place where people enter.","example":"The box is near the entrance."},{"word":"condition","part_of_speech":"noun","translation_fr":"état","definition":"The state something is in.","example":"They ask for books in good condition."},{"word":"return","part_of_speech":"verb","translation_fr":"rendre","definition":"To give something back.","example":"Children return a book first."},{"word":"damaged","part_of_speech":"adjective","translation_fr":"abîmé","definition":"Harm has changed its condition.","example":"Two books have damaged pages."},{"word":"willingness","part_of_speech":"noun","translation_fr":"volonté, disposition","definition":"Being ready to do something.","example":"They show a willingness to solve problems."}],"questions":[{"type":"mcq","question":"What does Esther suggest?","options":["A community book box","A new school","A sports competition","A book shop"],"answer":"A community book box","explanation_fr":"Elle propose une boîte pour partager les livres."},{"type":"mcq","question":"What happens after the meeting moves on?","options":["Esther asks two neighbours to help","The box opens immediately","The manager collects books","Children stop reading"],"answer":"Esther asks two neighbours to help","explanation_fr":"Elle choisit une prochaine action avec deux personnes."},{"type":"mcq","question":"Where can they place the box?","options":["Near the community centre entrance","Inside Esther's bedroom","At the market","On a wet road"],"answer":"Near the community centre entrance","explanation_fr":"Le responsable autorise cet emplacement."},{"type":"mcq","question":"Who paints the box?","options":["One neighbour","Esther's teacher","The manager","A child"],"answer":"One neighbour","explanation_fr":"Un des voisins peint la boîte."},{"type":"mcq","question":"How many books do they collect?","options":["Twelve","Five","Twenty","Two"],"answer":"Twelve","explanation_fr":"Ils collectent douze livres pendant la première semaine."},{"type":"mcq","question":"What should children do before taking another book?","options":["Return a book","Paint the box","Buy a notebook","Write a story"],"answer":"Return a book","explanation_fr":"Cette règle organise le partage."},{"type":"mcq","question":"Why are two books excluded?","options":["They have damaged pages","They are too popular","They are dry","They have titles"],"answer":"They have damaged pages","explanation_fr":"Le groupe ne garde pas les livres abîmés."},{"type":"true_false","question":"The group solves every future problem before starting.","options":["True","False"],"answer":"False","explanation_fr":"Ils commencent puis résolvent les problèmes qui apparaissent."},{"type":"true_false","question":"The project remains only a conversation.","options":["True","False"],"answer":"False","explanation_fr":"La boîte et les livres deviennent réels."},{"type":"open","question":"Who could help you take the first step on a community idea?","options":[],"answer":"I can ask two people to share the tasks, speak to the responsible person and test the idea with a small group.","explanation_fr":"La réponse doit proposer des partenaires et une première étape responsable."}],"grammar":[{"point":"Modal should for a rule","explanation_fr":"Should exprime ici une règle ou une conduite attendue.","example":"Children should return a book before taking another one."},{"point":"Require plus noun phrase","explanation_fr":"Require présente ce qui est nécessaire pour réussir une action.","example":"Action requires a responsible first step."}],"discussion":["Which idea in your community needs a next action?","How can people share the work?","Which problem can you solve after starting?"]},
  {"level":"B1","title":"Start Before the Plan Is Perfect","body":"A good plan can save time and prevent mistakes. Yet planning can also become a comfortable way to delay action. You compare tools, rewrite lists and imagine different versions of the project, but nothing outside your notebook changes.\n\nThe solution is not to act without thinking. It is to identify the smallest useful action that can teach you something. If you want to organise a study group, you do not need a detailed programme for the whole year. You could invite three people, choose one text and test a thirty-minute meeting.\n\nThis first action should have a clear purpose. The purpose might be to discover whether the chosen time suits everyone or whether the activity is useful. When the meeting ends, ask what worked and what needs to change. The experience gives you information that planning alone could not provide.\n\nSome preparation remains essential. A project involving money, safety or other people's personal information needs careful rules before it begins. Starting small does not mean ignoring responsibility. It means choosing a test whose risks you understand and can manage.\n\nAction also changes motivation. An idea that stays in your mind can feel either wonderful or impossible because there is no evidence to challenge your imagination. A small real attempt produces something more balanced. You may discover that the work is more interesting than expected, or that one part needs support.\n\nAfter the first step, you can plan with greater accuracy. You know more about time, resources and difficulties. The next version of the project is based on experience rather than guesses.\n\nTurning ideas into action is therefore a cycle: think, choose a responsible step, try it, learn and adjust. The goal is not to avoid every mistake. It is to make each step useful enough to improve the next one.","summary_fr":"Pour éviter que la planification ne retarde tout, il faut choisir un petit test responsable avec un but clair, examiner les résultats puis améliorer le projet par cycles d'action et d'apprentissage.","translation_fr":"Un bon plan peut faire gagner du temps et éviter des erreurs. Pourtant, planifier peut aussi devenir une façon confortable de retarder l'action. Vous comparez les outils, réécrivez les listes et imaginez différentes versions du projet, mais rien ne change hors de votre carnet.\n\nLa solution n'est pas d'agir sans réfléchir. Il s'agit d'identifier la plus petite action utile qui peut vous apprendre quelque chose. Si vous voulez organiser un groupe d'étude, vous n'avez pas besoin d'un programme détaillé pour toute l'année. Vous pourriez inviter trois personnes, choisir un texte et tester une réunion de trente minutes.\n\nCette première action doit avoir un but clair. Le but pourrait être de découvrir si l'horaire convient à tous ou si l'activité est utile. Quand la réunion se termine, demandez ce qui a fonctionné et ce qui doit changer. L'expérience fournit des informations que la planification seule ne pouvait pas donner.\n\nUne certaine préparation reste essentielle. Un projet impliquant de l'argent, la sécurité ou les informations personnelles d'autres personnes a besoin de règles attentives avant de commencer. Commencer petit ne signifie pas ignorer la responsabilité. Cela signifie choisir un test dont vous comprenez et maîtrisez les risques.\n\nL'action change aussi la motivation. Une idée qui reste dans votre esprit peut sembler merveilleuse ou impossible parce qu'aucune preuve ne vient contester votre imagination. Une petite tentative réelle produit quelque chose de plus équilibré. Vous pouvez découvrir que le travail est plus intéressant que prévu ou qu'une partie a besoin de soutien.\n\nAprès le premier pas, vous pouvez planifier avec plus de précision. Vous en savez plus sur le temps, les ressources et les difficultés. La prochaine version du projet repose sur l'expérience plutôt que sur des suppositions.\n\nTransformer les idées en actions est donc un cycle : réfléchir, choisir une étape responsable, essayer, apprendre et ajuster. Le but n'est pas d'éviter chaque erreur. Il est de rendre chaque étape assez utile pour améliorer la suivante.","knowledge_point":"L'apprenant apprend à remplacer la planification excessive par un test responsable, puis à utiliser l'expérience pour améliorer le plan.","vocabulary":[{"word":"delay","part_of_speech":"verb","translation_fr":"retarder","definition":"To make something happen later.","example":"Planning can delay action."},{"word":"identify","part_of_speech":"verb","translation_fr":"identifier","definition":"To recognise and name something.","example":"Identify the smallest useful action."},{"word":"test","part_of_speech":"verb","translation_fr":"tester","definition":"To try something to learn about it.","example":"Test a thirty-minute meeting."},{"word":"essential","part_of_speech":"adjective","translation_fr":"essentiel","definition":"Completely necessary.","example":"Some preparation remains essential."},{"word":"manage","part_of_speech":"verb","translation_fr":"maîtriser, gérer","definition":"To control or deal with something successfully.","example":"Choose risks you can manage."},{"word":"evidence","part_of_speech":"noun","translation_fr":"preuve","definition":"Information showing what is true.","example":"A real attempt provides evidence."},{"word":"accurate","part_of_speech":"adjective","translation_fr":"précis, exact","definition":"Correct and based on facts.","example":"Experience supports accurate planning."},{"word":"cycle","part_of_speech":"noun","translation_fr":"cycle","definition":"A series of actions repeated in order.","example":"Think, act and learn in a cycle."}],"questions":[{"type":"mcq","question":"How can planning delay action?","options":["You keep comparing and rewriting without changing anything real","It always prevents mistakes","It produces too much evidence","It makes every test responsible"],"answer":"You keep comparing and rewriting without changing anything real","explanation_fr":"La planification peut rester entièrement dans le carnet."},{"type":"mcq","question":"What is a good first step for a study group?","options":["Invite three people for one short meeting","Write a complete yearly programme","Buy every possible tool","Wait for a perfect plan"],"answer":"Invite three people for one short meeting","explanation_fr":"Un petit test permet d'apprendre rapidement."},{"type":"mcq","question":"What should the first action have?","options":["A clear purpose","No risks or rules","A full year of activities","A guaranteed result"],"answer":"A clear purpose","explanation_fr":"Le test doit répondre à une question utile."},{"type":"mcq","question":"What should you ask after the meeting?","options":["What worked and what needs to change","Why planning is always useless","How to avoid all feedback","Who should be blamed"],"answer":"What worked and what needs to change","explanation_fr":"Le bilan transforme l'expérience en apprentissage."},{"type":"mcq","question":"Which projects need careful rules before starting?","options":["Those involving money, safety or personal information","Only projects with three people","Only creative projects","Projects with no impact on others"],"answer":"Those involving money, safety or personal information","explanation_fr":"Ces domaines exigent une préparation responsable."},{"type":"mcq","question":"How can action change motivation?","options":["Real evidence challenges imagination","It guarantees excitement","It removes every difficulty","It makes support unnecessary"],"answer":"Real evidence challenges imagination","explanation_fr":"L'expérience offre une vision plus équilibrée que l'imagination seule."},{"type":"mcq","question":"What improves the next plan?","options":["Knowledge gained from the first attempt","More guesses","Avoiding all mistakes","A longer list without action"],"answer":"Knowledge gained from the first attempt","explanation_fr":"Le plan suivant repose sur l'expérience."},{"type":"true_false","question":"Starting small means ignoring responsibility.","options":["True","False"],"answer":"False","explanation_fr":"Le test doit avoir des risques compris et maîtrisés."},{"type":"true_false","question":"The action cycle includes learning and adjusting.","options":["True","False"],"answer":"True","explanation_fr":"Le cycle associe réflexion, essai, apprentissage et ajustement."},{"type":"open","question":"Describe a small responsible test for one of your ideas.","options":[],"answer":"I will test one short session with three people, protect their information, and ask what worked before planning the next session.","explanation_fr":"La réponse doit préciser le test, sa responsabilité et son bilan."}],"grammar":[{"point":"If for a possible project","explanation_fr":"If introduit une condition réelle avec présent simple et futur ou modal dans la proposition principale.","example":"If you want to organise a study group, you could invite three people."},{"point":"Rather than guesses","explanation_fr":"Rather than indique ce sur quoi le projet ne repose plus.","example":"The next version is based on experience rather than guesses."}],"discussion":["When has planning delayed one of your ideas?","What responsible test could you try?","What information can action provide that planning cannot?"]},
  {"level":"B2","title":"Execution Turns Assumptions into Evidence","body":"Before a project begins, much of its design rests on assumptions. We assume that people need the service, that the schedule is realistic and that we will enjoy the work. Planning organises these assumptions, but it cannot confirm them on its own. Execution introduces contact with reality.\n\nA useful first version is not necessarily small because the ambition is small. It is small because the team wants to learn before committing too many resources. A training organisation, for example, could test one workshop with a limited group before designing a complete annual programme. The workshop would reveal whether the chosen time, materials and level of support actually help participants.\n\nTo make action informative, decide what you are trying to learn. Without a clear question, a busy week can produce many activities but little understanding. A question such as \"Can participants complete the exercise without individual assistance?\" directs attention to a specific part of the design.\n\nExecution also exposes interdependencies. A task that appears simple in a list may depend on another person's approval, a delivery or access to a room. When the project moves, these connections become visible. The team can then assign responsibility and adjust the sequence instead of discovering the problem at the final deadline.\n\nNot every setback should be interpreted as failure. A low attendance figure may reflect the schedule rather than the content. Confused participants may need clearer instructions rather than a completely different programme. Good execution includes observation and diagnosis before major changes.\n\nHowever, learning should not become an excuse for endless experimentation. At some point, the evidence is sufficient for a decision: continue, modify, pause or stop. Repeating the same test without changing anything rarely adds useful knowledge.\n\nAction is therefore not the opposite of thought. Well-designed action produces the information that thought needs. It turns assumptions into evidence, reveals practical connections and gives the next decision a stronger foundation.","summary_fr":"L'exécution teste les hypothèses du projet et révèle les dépendances pratiques. Un test doit viser un apprentissage précis, distinguer les causes des difficultés et aboutir à une décision.","translation_fr":"Avant le début d'un projet, une grande partie de sa conception repose sur des hypothèses. Nous supposons que les gens ont besoin du service, que le calendrier est réaliste et que nous aimerons le travail. La planification organise ces hypothèses, mais ne peut pas les confirmer seule. L'exécution établit un contact avec la réalité.\n\nUne première version utile n'est pas nécessairement petite parce que l'ambition est petite. Elle est petite parce que l'équipe veut apprendre avant d'engager trop de ressources. Un organisme de formation, par exemple, pourrait tester un atelier avec un groupe limité avant de concevoir un programme annuel complet. L'atelier révélerait si l'horaire, les supports et le niveau d'accompagnement aident réellement les participants.\n\nPour rendre l'action instructive, décidez ce que vous cherchez à apprendre. Sans question claire, une semaine chargée peut produire beaucoup d'activités mais peu de compréhension. Une question comme « Les participants peuvent-ils terminer l'exercice sans aide individuelle ? » dirige l'attention vers une partie précise de la conception.\n\nL'exécution expose aussi les interdépendances. Une tâche qui semble simple dans une liste peut dépendre de l'accord d'une autre personne, d'une livraison ou de l'accès à une salle. Quand le projet avance, ces liens deviennent visibles. L'équipe peut alors attribuer les responsabilités et ajuster la séquence au lieu de découvrir le problème à l'échéance finale.\n\nChaque revers ne doit pas être interprété comme un échec. Une faible participation peut refléter l'horaire plutôt que le contenu. Des participants confus peuvent avoir besoin d'instructions plus claires plutôt que d'un programme complètement différent. Une bonne exécution comprend l'observation et le diagnostic avant les grands changements.\n\nCependant, apprendre ne doit pas devenir une excuse pour expérimenter sans fin. À un moment, les preuves suffisent pour décider : continuer, modifier, suspendre ou arrêter. Répéter le même test sans rien changer ajoute rarement une connaissance utile.\n\nL'action n'est donc pas le contraire de la pensée. Une action bien conçue produit les informations dont la pensée a besoin. Elle transforme les hypothèses en preuves, révèle les liens pratiques et donne à la prochaine décision une base plus solide.","knowledge_point":"L'apprenant comprend comment une exécution conçue pour apprendre teste les hypothèses, révèle les dépendances et prépare une décision fondée sur des preuves.","vocabulary":[{"word":"assumption","part_of_speech":"noun","translation_fr":"hypothèse","definition":"Something accepted as true before proof.","example":"Planning organises assumptions."},{"word":"execution","part_of_speech":"noun","translation_fr":"exécution","definition":"The process of putting a plan into action.","example":"Execution introduces contact with reality."},{"word":"commit","part_of_speech":"verb","translation_fr":"engager","definition":"To decide to use resources or effort.","example":"Learn before committing too many resources."},{"word":"informative","part_of_speech":"adjective","translation_fr":"instructif","definition":"Providing useful information.","example":"Make the action informative."},{"word":"interdependency","part_of_speech":"noun","translation_fr":"interdépendance","definition":"A relationship in which tasks or people depend on one another.","example":"Execution exposes interdependencies."},{"word":"assign","part_of_speech":"verb","translation_fr":"attribuer","definition":"To give a task or responsibility to someone.","example":"Assign responsibility for each task."},{"word":"setback","part_of_speech":"noun","translation_fr":"revers","definition":"A problem that delays progress.","example":"A setback is not always failure."},{"word":"diagnosis","part_of_speech":"noun","translation_fr":"diagnostic","definition":"Identifying the cause of a problem.","example":"Observe and make a diagnosis before changing everything."}],"questions":[{"type":"mcq","question":"What does planning organise but not confirm?","options":["Assumptions","Final evidence","Participant feedback","Practical dependencies"],"answer":"Assumptions","explanation_fr":"La planification organise les hypothèses sans les valider seule."},{"type":"mcq","question":"Why can a first version be small?","options":["To learn before committing many resources","Because the ambition must remain small","To avoid all decisions","To hide practical problems"],"answer":"To learn before committing many resources","explanation_fr":"La petite échelle réduit l'engagement pendant l'apprentissage."},{"type":"mcq","question":"What could one test workshop reveal?","options":["Whether time, materials and support help participants","That an annual programme is already perfect","That no feedback is needed","That every assumption is true"],"answer":"Whether time, materials and support help participants","explanation_fr":"Le test examine ces éléments concrets."},{"type":"mcq","question":"What makes action informative?","options":["A clear learning question","A busy schedule","Many unrelated activities","Repeating the same test forever"],"answer":"A clear learning question","explanation_fr":"La question dirige l'observation vers un aspect précis."},{"type":"mcq","question":"Which is an interdependency?","options":["A task depends on another person's approval","A task appears in a list","A participant completes an exercise","A team reviews evidence"],"answer":"A task depends on another person's approval","explanation_fr":"Cette relation lie l'avancement à une autre personne."},{"type":"mcq","question":"What might low attendance indicate?","options":["The schedule rather than the content","That the programme must always stop","That participants learned nothing","That every assumption is false"],"answer":"The schedule rather than the content","explanation_fr":"Il faut diagnostiquer la cause avant de changer le programme."},{"type":"mcq","question":"When should experimentation lead to a decision?","options":["When the evidence is sufficient","Only after endless repetition","Before any test occurs","When no learning question exists"],"answer":"When the evidence is sufficient","explanation_fr":"Continuer, modifier, suspendre ou arrêter devient alors possible."},{"type":"true_false","question":"Repeating an unchanged test always adds useful knowledge.","options":["True","False"],"answer":"False","explanation_fr":"La répétition identique apporte rarement une information nouvelle."},{"type":"true_false","question":"Well-designed action can support better thinking.","options":["True","False"],"answer":"True","explanation_fr":"L'action produit les informations nécessaires à la réflexion."},{"type":"open","question":"State one project assumption and an action that could test it.","options":[],"answer":"I assume the workshop time suits participants. I can test one session with a small group and measure attendance and completion before expanding it.","explanation_fr":"La réponse doit relier une hypothèse à un test observable et limité."}],"grammar":[{"point":"Whether for an open question","explanation_fr":"Whether introduit la question indirecte que le test doit trancher.","example":"The workshop reveals whether the chosen time helps participants."},{"point":"Rather than for diagnosis","explanation_fr":"Rather than oppose une explication possible à une autre.","example":"Low attendance may reflect the schedule rather than the content."}],"discussion":["Which assumption is currently guiding one of your projects?","What could a small execution test reveal?","When would you stop experimenting and decide?"]},
  {"level":"C1","title":"Action as a Form of Inquiry","body":"Action is commonly described as what happens after thinking is complete. In practice, complex projects rarely offer that luxury. The available information is partial, conditions change and some questions cannot be answered in advance. Under these circumstances, action can become a form of inquiry: a disciplined way of discovering what contemplation alone cannot establish.\n\nThis does not justify impulsiveness. An action designed to produce learning differs from an action designed merely to display momentum. The first identifies an uncertainty, chooses a bounded intervention and specifies what would count as useful evidence. The second may generate impressive activity while leaving every important assumption untouched.\n\nConsider an organisation developing a new course. A beautifully detailed curriculum can still conceal basic uncertainties about learners' prior knowledge, available time and preferred support. A pilot session addresses some of these uncertainties by putting a limited version into contact with real participants. Its value lies not only in whether participants enjoy it, but in what their performance reveals about the design.\n\nInquiry through action also requires interpretive restraint. A disappointing result does not automatically invalidate the whole idea, just as enthusiasm does not prove effectiveness. Observers should separate the outcome from its possible causes. Was the instruction unclear, the timing unsuitable or the exercise beyond the group's current competence? Each explanation implies a different response.\n\nMoreover, some consequences cannot ethically be treated as experimental costs. When an intervention risks safety, dignity or essential resources, the burden of preparation becomes much greater. Learning by doing is not a universal permission to expose others to harm for the benefit of the planner's insight.\n\nOnce evidence emerges, the process must include decision and consolidation. Teams sometimes enjoy experimentation because it postpones the discomfort of commitment. Yet a pilot that never leads to a revised design, a clear stop or a responsible expansion has not fulfilled its purpose.\n\nAction as inquiry therefore unites movement with intellectual discipline. It accepts that knowledge may be incomplete, but refuses to make that incompleteness an excuse for either paralysis or carelessness. The strongest next step is one whose results can genuinely change what you think and what you do next.","summary_fr":"Dans un projet complexe, l'action peut servir à apprendre si elle teste une incertitude avec des limites et des preuves. Elle exige aussi prudence d'interprétation, responsabilité éthique et une décision finale.","translation_fr":"L'action est communément décrite comme ce qui arrive lorsque la réflexion est terminée. En pratique, les projets complexes offrent rarement ce luxe. Les informations disponibles sont partielles, les conditions changent et certaines questions ne peuvent pas être résolues à l'avance. Dans ces circonstances, l'action peut devenir une forme d'investigation : une manière disciplinée de découvrir ce que la contemplation seule ne peut établir.\n\nCela ne justifie pas l'impulsivité. Une action conçue pour produire un apprentissage diffère d'une action conçue simplement pour montrer un élan. La première identifie une incertitude, choisit une intervention limitée et précise ce qui compterait comme preuve utile. La seconde peut produire une activité impressionnante tout en laissant chaque hypothèse importante intacte.\n\nPrenons une organisation qui développe un nouveau cours. Un programme magnifiquement détaillé peut encore cacher des incertitudes fondamentales sur les connaissances antérieures des apprenants, leur temps disponible et le soutien préféré. Une séance pilote aborde certaines de ces incertitudes en mettant une version limitée en contact avec de vrais participants. Sa valeur réside non seulement dans leur plaisir, mais dans ce que leur performance révèle sur la conception.\n\nL'investigation par l'action exige aussi une retenue interprétative. Un résultat décevant n'invalide pas automatiquement toute l'idée, de même que l'enthousiasme ne prouve pas l'efficacité. Les observateurs doivent séparer le résultat de ses causes possibles. L'instruction était-elle confuse, l'horaire inadapté ou l'exercice au-delà de la compétence actuelle du groupe ? Chaque explication implique une réponse différente.\n\nDe plus, certaines conséquences ne peuvent éthiquement être traitées comme des coûts expérimentaux. Quand une intervention risque la sécurité, la dignité ou des ressources essentielles, la charge de préparation devient beaucoup plus grande. Apprendre en faisant n'est pas une permission universelle d'exposer les autres à un dommage pour éclairer le planificateur.\n\nUne fois les preuves apparues, le processus doit inclure une décision et une consolidation. Les équipes apprécient parfois l'expérimentation parce qu'elle retarde l'inconfort de l'engagement. Pourtant, un pilote qui ne mène jamais à une conception révisée, à un arrêt clair ou à une extension responsable n'a pas rempli son rôle.\n\nL'action comme investigation associe donc mouvement et discipline intellectuelle. Elle accepte que la connaissance soit incomplète, mais refuse que cette incomplétude excuse soit la paralysie, soit la négligence. Le meilleur prochain pas est celui dont les résultats peuvent réellement changer ce que vous pensez et ce que vous ferez ensuite.","knowledge_point":"L'apprenant conçoit l'action comme investigation disciplinée, avec hypothèses, limites éthiques, interprétation prudente et décision fondée sur les résultats.","vocabulary":[{"word":"inquiry","part_of_speech":"noun","translation_fr":"investigation, recherche","definition":"A process of asking questions and discovering information.","example":"Action can become a form of inquiry."},{"word":"bounded","part_of_speech":"adjective","translation_fr":"délimité","definition":"Limited within clear boundaries.","example":"Choose a bounded intervention."},{"word":"momentum","part_of_speech":"noun","translation_fr":"élan","definition":"The impression or force of continuing movement.","example":"Activity may merely display momentum."},{"word":"pilot","part_of_speech":"noun","translation_fr":"projet pilote","definition":"A small test before wider implementation.","example":"A pilot session tests the course design."},{"word":"restraint","part_of_speech":"noun","translation_fr":"retenue","definition":"Careful control of actions or conclusions.","example":"Interpretive restraint prevents hasty conclusions."},{"word":"invalidate","part_of_speech":"verb","translation_fr":"invalider","definition":"To show that something is not valid.","example":"One result does not invalidate the whole idea."},{"word":"consolidation","part_of_speech":"noun","translation_fr":"consolidation","definition":"Making learning or a position stronger and more stable.","example":"The process includes decision and consolidation."},{"word":"paralysis","part_of_speech":"noun","translation_fr":"paralysie","definition":"An inability to act or decide.","example":"Incomplete knowledge should not cause paralysis."}],"questions":[{"type":"mcq","question":"When can action become a form of inquiry?","options":["When some questions cannot be answered before trying","Only when all information is complete","Whenever speed is impressive","Only after thinking is finished"],"answer":"When some questions cannot be answered before trying","explanation_fr":"L'action découvre ce que la contemplation seule ne peut établir."},{"type":"mcq","question":"What does an action designed for learning identify?","options":["An uncertainty, a bounded intervention and useful evidence","Only a way to display momentum","Every possible assumption as true","A reason to avoid commitment"],"answer":"An uncertainty, a bounded intervention and useful evidence","explanation_fr":"Ces trois éléments distinguent l'investigation de l'activité spectaculaire."},{"type":"mcq","question":"What can a detailed curriculum still conceal?","options":["Uncertainties about learners and support","Every participant's actual performance","All evidence from a pilot","The need for interpretation"],"answer":"Uncertainties about learners and support","explanation_fr":"Le document seul ne révèle pas les connaissances, le temps ou le soutien nécessaire."},{"type":"mcq","question":"What is valuable about participants' performance?","options":["What it reveals about the design","Only whether participants are enthusiastic","Its ability to prove everything","Its freedom from interpretation"],"answer":"What it reveals about the design","explanation_fr":"La performance fournit des informations sur le fonctionnement du cours."},{"type":"mcq","question":"Why is interpretive restraint necessary?","options":["Different causes imply different responses","Every disappointing result invalidates the idea","Enthusiasm always proves effectiveness","Observation removes all uncertainty"],"answer":"Different causes imply different responses","explanation_fr":"Il faut distinguer les causes avant de choisir une correction."},{"type":"mcq","question":"When does the burden of preparation increase?","options":["When safety, dignity or essential resources are at risk","Whenever a pilot is enjoyable","Only when no learning occurs","When a design is revised"],"answer":"When safety, dignity or essential resources are at risk","explanation_fr":"Ces enjeux imposent une préparation et une protection plus fortes."},{"type":"mcq","question":"What must follow evidence from a pilot?","options":["Decision and consolidation","Endless experimentation","Avoidance of commitment","No change in thinking"],"answer":"Decision and consolidation","explanation_fr":"Le test doit mener à réviser, arrêter ou étendre de façon responsable."},{"type":"true_false","question":"Learning by doing permits exposing others to harm for insight.","options":["True","False"],"answer":"False","explanation_fr":"Le texte refuse explicitement cette justification."},{"type":"true_false","question":"Incomplete knowledge can justify both care and action.","options":["True","False"],"answer":"True","explanation_fr":"Elle n'excuse ni paralysie ni négligence."},{"type":"open","question":"Design an action whose result could genuinely change your next decision.","options":[],"answer":"I will test one bounded lesson, define the evidence needed, protect participants, and decide afterwards whether to revise, stop or expand it.","explanation_fr":"La réponse doit relier test, preuves, responsabilité et décision."}],"grammar":[{"point":"Not only but for added value","explanation_fr":"Not only... but... ajoute une information plus importante à une première observation.","example":"Its value lies not only in whether participants enjoy it, but in what their performance reveals."},{"point":"Either or for rejected extremes","explanation_fr":"Either... or... présente ici deux réactions extrêmes qui sont toutes deux refusées.","example":"Incompleteness is no excuse for either paralysis or carelessness."}],"discussion":["Which uncertainty could a small action help you investigate?","How do you avoid interpreting one result too quickly?","What decision must follow a successful pilot?"]}
 ]$content$::jsonb) as x(level public.rw_level,title text,body text,summary_fr text,translation_fr text,knowledge_point text,vocabulary jsonb,questions jsonb,grammar jsonb,discussion jsonb)
)
insert into public.rw_lessons(session_id,level,title,body,word_count,summary_fr,translation_fr,knowledge_point,vocabulary,questions,grammar,discussion,mention,status,content_type,rights_status,published_at)
select s.id,c.level,c.title,c.body,cardinality(regexp_split_to_array(btrim(c.body),'[[:space:]]+')),
 c.summary_fr,c.translation_fr,c.knowledge_point,c.vocabulary,c.questions,c.grammar,c.discussion,
 'original','published','original text','Texte original OpenDoorsClass',now()
from content c join public.rw_weeks w on w.week_number=4 join public.rw_sessions s on s.week_id=w.id and s.day_index=5
on conflict(session_id,level) do update set title=excluded.title,body=excluded.body,word_count=excluded.word_count,
 summary_fr=excluded.summary_fr,translation_fr=excluded.translation_fr,knowledge_point=excluded.knowledge_point,
 vocabulary=excluded.vocabulary,questions=excluded.questions,grammar=excluded.grammar,discussion=excluded.discussion,
 mention='original',status='published',content_type='original text',rights_status='Texte original OpenDoorsClass',
 published_at=coalesce(rw_lessons.published_at,now()) where rw_lessons.status<>'published';
do $$ declare invalid_count integer; begin
 select count(*) into invalid_count from public.rw_lessons l join public.rw_sessions s on s.id=l.session_id
 join public.rw_weeks w on w.id=s.week_id where w.week_number=4 and s.day_index=5 and
 (l.status<>'published' or jsonb_array_length(l.questions)<>10 or jsonb_array_length(l.vocabulary)<8
 or jsonb_array_length(l.grammar)<>2 or jsonb_array_length(l.discussion)<>3 or l.body='' or coalesce(l.translation_fr,'')='');
 if invalid_count<>0 then raise exception 'Validation impossible: % leçons incomplètes',invalid_count; end if;
end $$;